csui.define('csui/utils/commands/switch.table.mode.wrap',[
  'require',
  'csui/models/command',
  'csui/utils/commands/table.settings',
], function (require, CommandModel, TableSettingsCommand) {
  'use strict';

  const SwitchTableModeWrapCommand = CommandModel.extend({
    defaults: {
      signature: "TableModeWrap"
    },

    tableModeWrap: 'wrap',

    enabled: function (status) {
      if (TableSettingsCommand.isEnabled) {
        return false; // if table mode settings command is enabled, disable the "old" toggle icon
      }
      if (!status.originatingView || !typeof status.originatingView.getTableMode === 'function' ||
          !typeof status.originatingView.setTableMode === 'function') {
        return false; // originating view is not a nodestable.view with getTableMode and setTableMode functions
      }

      // only enable if table mode is not already 'wrap'
      return status.originatingView.getTableMode() !== this.tableModeWrap;
    },

    execute: function (status, options) {
      const nodesTableView = status.originatingView;
      nodesTableView.setTableMode(this.tableModeWrap).catch((error) => {
        throw error;
      });
    }

  });

  return SwitchTableModeWrapCommand;
});
