csui.define('csui/utils/commands/switch.table.mode.thumbnail',[
  'require',
  'csui/models/command',
  'csui/utils/commands/table.settings',
  "csui/utils/accessibility",
], function (require, CommandModel, TableSettingsCommand, Accessibility) {
  'use strict';

  const accessibleTable = Accessibility.isAccessibleTable();

  const SwitchTableModeThumbnailCommand = CommandModel.extend({
    defaults: {
      signature: "TableModeThumbnail"
    },

    tableModeThumbnail: 'thumbnail',

    enabled: function (status) {
      if (accessibleTable) {
        const itemValue = status.toolItem.get('itemValue');
        if (itemValue === this.tableModeThumbnail) {
          return false; // thumbnail mode is not for accessible table
        }
      }
      if (TableSettingsCommand.isEnabled) {
        return false; // if table mode settings command is enabled, disable the "old" toggle icon
      }
      const thumbnailToggleConfig = require.moduleConfig('csui/utils/commands/thumbnail.toggle');
      if (!thumbnailToggleConfig.enableGridView) {
        return false;
      }
      if (!status.originatingView || !(typeof status.originatingView.getTableMode === 'function') ||
          !(typeof status.originatingView.setTableMode === 'function')) {
        return false; // originating view is not a nodestable.view with getTableMode and setTableMode functions
      }

      // only enable if table mode is not already 'thumbnail'
      return status.originatingView.getTableMode() !== this.tableModeThumbnail;
    },

    execute: function (status, options) {
      const nodesTableView = status.originatingView;
      nodesTableView.setTableMode(this.tableModeThumbnail).catch((error) => {
        throw error;
      });
    }

  });

  return SwitchTableModeThumbnailCommand;
});
