csui.define('csui/utils/commands/table.settings',[
  'module', 'nuc/lib/underscore',
  'csui/models/command'
], function (module, _, CommandModel) {
  'use strict';

  const config = module.config();
  _.defaults(config, {
    enabled: false, // setting enabled to true will automatically disable switch.table.mode.thumbnail.js and
    // switch.table.mode.wrap.js
  });

  const TableSettingsCommand = CommandModel.extend({
    defaults: {
      signature: "TableSettings"
    },

    enabled: function (status) {
      // note: explicitly check for config.enabled not being false to enable it if this setting is not in
      // csui-extensions.json
      return config.enabled && status.originatingView && typeof status.originatingView.getTableMode === 'function' &&
             typeof status.originatingView.setTableMode === 'function';
    },

    // This command is not to be executed.
  });

  TableSettingsCommand.isEnabled = config.enabled;  // provide this class value for "old" commands to disable/enable
  return TableSettingsCommand;
});
