csui.define('csui/utils/commands/versions/make.generation',[
    'csui/lib/underscore', 'csui/lib/jquery',
    'i18n!csui/utils/commands/versions/nls/localized.strings',
    'csui/utils/commandhelper', 'csui/models/command',
    'csui/utils/base', 'csui/utils/url'
  ], function (_, $, versionLang, CommandHelper, Command, base, Url) {
    'use strict';

    // Note:
    // There's no generic way to handle required metadata currently.
    // inlineformview does the same separately but doesn't make it reusable.
    // MetadataAddItemController gives the api but requires a fileupload collection.
    // Once there's a generic approach available, stop mocking file upload in favour of that.
    // since this approach needs a few temporary-fixes to work.

    // Dependencies loaded in the execute method first
    var ConflictResolver, UploadFileCollection, GlobalMessage, NodeLinks, NextNodeModelFactory;

    var MakeGenerationCommand = Command.extend({
      defaults: {
        signature: 'VersionMakeGeneration',
        command_key: ['makegeneration'],
        name: versionLang.CommandNameMakeGeneration,
        verb: versionLang.CommandVerbMakeGeneration,
        scope: 'single'
      },

      enabled: function (status, options) {
        if(status.nodes.length !== 1) {
            return false;
        }

        var version = CommandHelper.getJustOneNode(status);
        return this._isActionAvalableInNode(version);
      },

      _isActionAvalableInNode: function (node) {
        if(!node || !node.actions) {
            return false;
        }
        var makeGenerationAction = node.actions.findWhere(function (action) {
            return action.id === 'makegeneration';
        });
        return makeGenerationAction !== undefined;
      },

      execute: function (status, options) {

        status.suppressSuccessMessage = true;
        status.suppressFailMessage = true;
        var deferred = $.Deferred();

        csui.require([
            'csui/controls/globalmessage/globalmessage',
            'csui/controls/conflict.resolver/conflict.resolver',
            'csui/models/fileuploads',
            'csui/utils/node.links/node.links',
            'csui/utils/contexts/factories/next.node'
          ], _.bind(function () {

            GlobalMessage = arguments[0];
            ConflictResolver = arguments[1];
            UploadFileCollection = arguments[2];
            NodeLinks = arguments[3];
            NextNodeModelFactory = arguments[4];

            var currentNode = status.container;
            status.version = CommandHelper.getJustOneNode(status);

            // prompt the user with a dialog to select the target location.
            this._selectTargetLocation(status, options).done(_.bind(function (selectedOptionInfo) {

                _.extend(status, {
                    updatedName: selectedOptionInfo.filterName,
                    targetContainer: selectedOptionInfo.nodes[0],
                    connector: currentNode ? currentNode.connector : selectedOptionInfo.nodes[0].connector
                });

                // Since the progress panel isn't re-usable for all scenarios,
                // and works in file-upload-progress scenario, we use it for now
                // by mocking file upload.

                // Another reason is the metadata add item controller exposes
                // methods to handle required attributes in the container
                // but isn't generic and expects a file upload collection.
                var uploadCollection = this._addToUploadCollection(status);

                // Check for naming conflicts once the target is selected.
                this._resolveNamingConflicts(uploadCollection, status)
                      .done(_.bind(function (resolvedItemsCollection) {

                        // Note: it is a tweak since the conflict resolver changes
                        // the type to 144 which comes from the back-end if the item
                        // is a FileUploadModel. This can be removed once the approach
                        // no longer requires upload collection.
                        resolvedItemsCollection.forEach(function (resolvedItem) {
                                resolvedItem.set({type: 2}, {silent:true});
                        });

                        // Allow the user to fill any missing required attribute values
                        // if present in the target container.
                        this._handleRequiredMetadata(resolvedItemsCollection, status)
                            .done(_.bind(function (ItemsCollection) {

                                // Once all the validations are done,
                                // make the API call to create a generation.
                                this._createGeneration(ItemsCollection, status)
                                    .done(_.bind(function (res) {
                                        // remove the delete action for the version.
                                        this._removeDeleteAction(status.version);
                                        deferred.resolve(res);
                                    }, this))
                                    .fail(function (error) {
                                        deferred.reject(error);
                                    });
                            }, this))
                            .fail(function (error) {
                                deferred.reject(error);
                            });

                    }, this))
                    .fail(function (error) {
                        deferred.reject(error);
                    });

            }, this))
            .fail(function (error) {
                deferred.reject(error);
            });

        }, this), function (error) {
            deferred.reject(error);
          });

        return deferred.promise();

      },

      _selectTargetLocation: function (status, options) {
        var deferred = $.Deferred();

        csui.require(['csui/dialogs/node.picker/node.picker'],
            _.bind(function (NodePicker) {

              var dialogTitle = versionLang.NameAsMakeGeneration,
                  initialContainer = this._getParentContainer(status);

              var pickerOptions = _.extend({
                selectableTypes: [-1],
                unselectableTypes: [899, 298],
                addableTypes: [0], // Allowing folders to add from picker. Revisit when LPAD-61637 done.
                showAllTypes: true,
                orderBy: 'type asc',
                saveFilter: true,
                initialFilter: status.version.get('name'),
                dialogTitle: dialogTitle,
                initialContainer: initialContainer,
                initialSelection: status.nodes,
                startLocation:  !initialContainer ? 'recent.containers' : '',
                globalSearch: true,
                disableSearchFromHere: true,
                context: options ? options.context : status.context,
                startLocations: ['enterprise.volume', 'current.location', 'personal.volume',
                  'favorites', 'recent.containers'],
                resolveShortcuts: true,
                resultOriginalNode: true,
                includeResources: ['show_hidden'],
                isKeyEvent: status?.toolItem?.get('isKeyEvent')
              }, status);

              this.nodePicker = new NodePicker(pickerOptions);
              this.originatingView = status.originatingView;
              this.nodePicker
                  .show()
                  .done(function () {
                    deferred.resolve.apply(deferred, arguments);
                  })
                  .fail(function () {
                    deferred.reject.apply(deferred, arguments);
                  });
            }, this), function (error) {
              deferred.reject(error);
            });
        return deferred.promise();
      },

      _getParentContainer: function (status) {
        var parentId;
        if(status.container) {
            parentId = status.container.get('parent_id');
        } else {
            parentId = status.version.get('id_expand') &&
                       status.version.get('id_expand').parent_id;
        }

        return parentId ? {id: parentId} : null;
      },

      _addToUploadCollection: function (options) {

        var uploadCollection = new UploadFileCollection();

        uploadCollection.add({
                file: {
                    name: options.updatedName || options.version.get('name'),
                    type: options.version.get('mime_type'),
                    // for total to be 1 in the upload model.
                    // used to reflect progress.
                    size: 1
                },
                name: options.updatedName || options.version.get('name'),
                container: options.targetContainer,
                original_id: options.version.get('id'),
                parent_id: options.targetContainer.get('id'),
                version_number: options.version.get('version_number'),
                type: 2,
                type_name: "Generation",
                targetLocation: {
                    id: options.targetContainer.get('id'),
                    url: NodeLinks.getUrl(options.targetContainer)
                }
            },
            {
                container: options.targetContainer,
                connector: options.connector,
                enforcedRequiredAttrs: true
            }
        );

        return uploadCollection;
      },

      _resolveNamingConflicts: function (items, options) {

        var conflictResolver = new ConflictResolver({
            h1Label: versionLang.ActionNameMakeGeneration,
            actionBtnLabel: versionLang.ActionTitleMakeGeneration,
            excludeAddVersion: true,
            container: options.targetContainer,
            files: items,
            originatingView: options.originatingView
        });

        return conflictResolver.run();
      },

      _handleRequiredMetadata: function (itemsCollection, options) {
        var deferred = $.Deferred();
        options.originatingView && options.originatingView._blockingCounter === 0 &&
        options.originatingView.blockActions();
        csui.require(['csui/widgets/metadata/impl/add.items/metadata.add.item.controller'
        ], function (MetadataAddItemController) {
          var currentModel = itemsCollection.first();
          var metadataController = new MetadataAddItemController();
          metadataController.addItemsRequiredMetadata(itemsCollection.models, {
            container: options && options.targetContainer,
            context: options.context,
            openMetadata: options.openMetadata,
            inheritance: options.inheritance,
            addableType: options.addableType || 2,
            dialogTitle: versionLang.ActionNameMakeGeneration,
            addButtonTitle: versionLang.ActionTitleMakeGeneration,
            // We pass already available data of the generation.
            // this will be needed to populate the general attributes during
            // metadata handling of missing required attributes.
            data: {
              original_id: currentModel.get('original_id'),
              version_number: currentModel.get('version_number')
            }
          }).done(function () {
                deferred.resolve(itemsCollection);
            })
            .fail(function () {
                deferred.reject();
            })
            .always(function () {
                options.originatingView && options.originatingView.unblockActions();
            });
        }, function (error) {
          deferred.reject(error);
        });
        return deferred.promise();
      },

      _createGeneration: function (itemsCollection, options) {

        var currentModel = itemsCollection.first(),
            name = currentModel.get('newName') || currentModel.get('name'),
            versionNumber = currentModel.get('version_number'),
            originalId = currentModel.get('original_id'),
            parentId = currentModel.get('parent_id'),
            extendedData = currentModel.get('extended_data'),
            deferred = $.Deferred();

        // gather data to be sent to the back-end.
        var data = {
            name: name,
            type: 2,
            version_number: versionNumber,
            original_id: originalId,
            parent_id: parentId
        };

        // check for multi-lingual info provided by the user.
        var mlDataEnabled = base.getMetadataLanguageInfo().enabled;
        if (mlDataEnabled && !!currentModel.get('multilingual_provided')) {
            _.extend(data, {
            name_multilingual: currentModel.get('name_multilingual')
            });
        }

        // additional attributes may come from metadata entered by the user
        if (extendedData) {
            _.deepExtend(data, extendedData);
        }

        var makegenerationOptions = {
            url: Url.combine(options.connector.getConnectionUrl().getApiBase('v1'), '/nodes'),
            method: 'POST',
            data: data,
            contentType: options.connector.getAjaxContentType()
        };

        options.connector.makeAjaxCall(makegenerationOptions)
                 .done(function (model) {
                    currentModel.set('count', 1);
                    // The progress panel uses the currentModel.node to navigate
                    // to the container location, but we neither use
                    // nor populate the node anywhere
                    // since it is not useful going forward.
                    // so, set it to null for now.

                    // TODO: remove this when the currentModel is needed
                    // which will then be populated.
                    currentModel.node = null;
                    currentModel.deferred.resolve(currentModel);
                    deferred.resolve(model);
                }).fail(function (error) {
                    currentModel.deferred.reject(currentModel, {message: error.responseText});
                    deferred.reject(error);
                });

        GlobalMessage.showProgressPanel(itemsCollection, {
            oneFileTitle: versionLang.ActionNameMakeGeneration,
            oneFileSuccess: versionLang.MessageSuccessMakeGeneration,
            oneFilePending: versionLang.ActionNameMakeGeneration,
            oneFileFailure: versionLang.MessageFailureMakeGeneration,
            enableCancel: false,
            context: options.context,
            nextNodeModelFactory: NextNodeModelFactory
        });

        return deferred.promise();

      },

      _removeDeleteAction: function (version) {
        // Once a generation is created for a version, it is not deletable.
        // so, remove the action from the collection if available
        // instead of re-fetching.
        if(!version || !version.actions || version.actions.length === 0) {
          return;
        }
        version.set('has_generation', true);
        var actionCollection = version.actions,
            updatedActions = actionCollection.filter(function (action) {
              return !(action.id === 'delete' || action.id === 'versions_delete');
            });

        if(updatedActions.length < actionCollection.length) {
            actionCollection.reset(updatedActions);
        }
      }

    });

    return MakeGenerationCommand;
  });
